<?php require 'includes/layout.php';require_login();if(user()['role']!=='admin'){http_response_code(403);exit('Admin only');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='add_question'){$q=trim($_POST['question']??'');$opts=array_map('trim',[$_POST['a']??'',$_POST['b']??'',$_POST['c']??'',$_POST['d']??'']);$correct=filter_var($_POST['correct']??'',FILTER_VALIDATE_INT);if($q&&count(array_filter($opts))===4&&$correct!==false&&$correct>=0&&$correct<=3){db()->prepare('INSERT INTO questions(question,option_a,option_b,option_c,option_d,correct_index) VALUES(?,?,?,?,?,?)')->execute(array_merge([$q],$opts,[$correct]));flash('Question added.');redirect('admin.php');}}
if($action==='delete_question'){$id=(int)($_POST['id']??0);db()->prepare('DELETE FROM questions WHERE id=?')->execute([$id]);flash('Question deleted.');redirect('admin.php');}}
$users=db()->query('SELECT id,username,email,role FROM users ORDER BY id DESC LIMIT 30')->fetchAll();$questions=db()->query('SELECT id,question FROM questions ORDER BY id DESC LIMIT 30')->fetchAll();$stats=['users'=>db()->query('SELECT COUNT(*) FROM users')->fetchColumn(),'scores'=>db()->query('SELECT COUNT(*) FROM scores')->fetchColumn(),'questions'=>db()->query('SELECT COUNT(*) FROM questions')->fetchColumn()];top('Admin Dashboard');?>
<div class="grid2"><?php foreach($stats as $name=>$count):?><div class="stat"><strong><?=e($count)?></strong><?=e(ucfirst($name))?></div><?php endforeach;?></div>
<div class="panel"><h2>Manage quiz questions</h2><form class="form" method="post"><?php csrf_field();?><input type="hidden" name="action" value="add_question"><label>Question<input name="question" required></label><?php foreach(['a','b','c','d'] as $letter):?><label>Option <?=strtoupper($letter)?><input name="<?=$letter?>" required></label><?php endforeach;?><label>Correct option<select name="correct"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></label><button class="btn">Add question</button></form><table><tr><th>Question</th><th>Action</th></tr><?php foreach($questions as $q):?><tr><td><?=e($q['question'])?></td><td><form method="post" class="inline-form"><?php csrf_field();?><input type="hidden" name="action" value="delete_question"><input type="hidden" name="id" value="<?=e($q['id'])?>"><button class="btn danger">Delete</button></form></td></tr><?php endforeach;?></table></div>
<div class="panel"><h2>Registered users (view only)</h2><table><tr><th>Username</th><th>Email</th><th>Role</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['username'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td></tr><?php endforeach;?></table></div><?php bottom(); ?>
